/// A type that has a canonical default random generator.
///
/// Conforming a type to `RandomGenerable` gives it a `generator` entry point that the
/// rest of the library — and code generated by the `@RandomGenerable` macro — can use
/// to produce values of the type:
///
/// ```swift
/// let value = Int.generator.run()          // any Int
/// let flag = Bool.generator.run()          // true or false
/// let word = String.generator.run()        // 8 random alphanumeric characters
/// ```
///
/// The library conforms the common standard-library types with deliberately simple,
/// documented defaults (see the extensions in this file). When a default doesn't fit —
/// an age that should be `18...99`, a name that should come from a curated list — you
/// don't change the conformance: you override at the use site, either by composing
/// generators directly or with the `@Gen` per-property override of the
/// `@RandomGenerable` macro (enabled by the `Derive` package trait).
///
/// Custom types can conform manually by returning any generator whose `Element` is
/// `Self`:
///
/// ```swift
/// struct Temperature { var celsius: Double }
///
/// extension Temperature: RandomGenerable {
///     static var generator: some RandomGenerator<Temperature> {
///         FloatGenerator(in: -40...50).map(Temperature.init)
///     }
/// }
/// ```
public protocol RandomGenerable {
    /// The concrete generator type that produces values of this type.
    associatedtype Generator: RandomGenerator where Generator.Element == Self

    /// The canonical default generator for this type.
    static var generator: Generator { get }
}

// MARK: - Integers

extension RandomGenerable where Self: FixedWidthInteger & Sendable {
    /// The default integer generator: uniform over the type's entire range.
    ///
    /// Full range is the only unopinionated choice, but it is rarely what a fixture
    /// wants to display — override with `@Gen(IntGenerator(in: ...))` or compose your
    /// own generator when you need bounded values.
    public static var generator: IntGenerator<Self> {
        IntGenerator(in: Self.min ... Self.max)
    }
}

extension Int: RandomGenerable {}
extension Int8: RandomGenerable {}
extension Int16: RandomGenerable {}
extension Int32: RandomGenerable {}
extension Int64: RandomGenerable {}
extension UInt: RandomGenerable {}
extension UInt8: RandomGenerable {}
extension UInt16: RandomGenerable {}
extension UInt32: RandomGenerable {}
extension UInt64: RandomGenerable {}

// MARK: - Floating point

extension RandomGenerable where Self: BinaryFloatingPoint & Sendable, Self.RawSignificand: FixedWidthInteger {
    /// The default floating-point generator: uniform over the unit interval `0...1`.
    public static var generator: FloatGenerator<Self> {
        FloatGenerator(in: 0...1)
    }
}

extension Double: RandomGenerable {}
extension Float: RandomGenerable {}

// MARK: - Bool

extension Bool: RandomGenerable {
    /// The default boolean generator: a fair coin flip.
    public static var generator: BoolGenerator {
        BoolGenerator()
    }
}

// MARK: - Characters and strings

extension Character: RandomGenerable {
    /// The default character generator: a random ASCII letter (a-z, A-Z).
    public static var generator: some RandomGenerator<Character> {
        RandomGenerators.letter
    }
}

extension String: RandomGenerable {
    /// The default string generator: 8 random alphanumeric characters.
    public static var generator: some RandomGenerator<String> {
        RandomGenerators.letterOrNumber.array(8).map { String($0) }
    }
}

// MARK: - Optionals and arrays

extension Optional: RandomGenerable where Wrapped: RandomGenerable {
    /// The default optional generator: the wrapped type's generator, `nil` half the time.
    public static var generator: some RandomGenerator<Wrapped?> {
        Wrapped.generator.orNil(probability: 0.5)
    }
}

extension Array: RandomGenerable where Element: RandomGenerable {
    /// The default array generator: 0 to 10 elements from the element type's generator.
    public static var generator: some RandomGenerator<[Element]> {
        Element.generator.arrayGenerator(IntGenerator(in: 0...10))
    }
}
